import numpy as np
def equation(eps, T, params):
    p = params
    L = np.log(eps)
    return (p[0]+p[1]*T+p[2]*T**2) + (p[3]+p[4]*T+p[5]*T**2)*L + (p[6]+p[7]*T)*eps**(p[8]+p[9]*T)

Tb=[T**k for k in range(4)]
def fitb(cols):
    X=np.column_stack([c*t for c in cols for t in Tb])
    co=np.linalg.lstsq(X,sigma,rcond=None)[0]
    r=sigma-X@co
    return np.mean(r**2)/np.var(sigma)
